        if why != "" { return why; }
        let real = self.real_in(l);
        if real != "" { return real; }
        if q != self.columns { return format!("x{} is not the next fresh column x{}", q, self.columns); }
        self.columns += 1;
        let mq = SvRow { cols: vec![q], ks: vec![m], constant: 0 };
        let below = match sv_row_sum(-1, l, 1, &mq) { Some(__nikaia_value) => __nikaia_value, None => return String::from("overflow") };
